    "description": "新华社巴黎10月17日电（记者孙毅）法国外长巴罗17日晚在社交媒体发文说，法国北部欧努瓦艾姆里市市长贝尔纳·博杜当天在约旦河西岸遭到以色列定居者暴力袭击。 巴罗说，以色列当局应立即逮捕肇事者，将其绳之以法，并制止此类犯罪暴力行为，根据国际法义务确保平民安全。 据法媒17日报道，当天一支载有欧洲外交官的车队在约旦河西岸遭到以色列定居者袭击。",
