    "content": "17/10/2026 - 23:36 成千上万的人在10月17日星期六走上法国各地的街头，抗议生活成本高涨；教育经费不足和公共服务的恶化。这次示威活动是由前黄背心和大学生、中学生；工会甚至农民的运动发起。根据组织者的最终统计，有80万人参与了行动和游行。在首都巴黎里昂、马赛、雷恩和南特等多个城市，示威活动中和之后发生了骚乱和严重破坏。 在巴黎，根据警方的说法，由黄背心和工会联合组织的游行队伍从共和国广场出发，途经马让塔大街和巴布斯街，前往克里希广场。同时，在多个地区，尤其是共和国广场，发生了冲突。执法部门介入，阻止…"
