    "pub_date": "2026-10-18 00:06:37",
    "author": "xujdan",
    "description": "周四交接后，为期五个月左右的第二份工作也就此收尾，回去路上心里难受，因为没朋友所以只能跟爸妈说，不过再次证明跟爸妈说也得不到什么好的慰藉，他们只会说那就再找没什么大不了，我可能更想听到“那就休息一下吧”。总之跟他们说完更烦了，我妈对我有迷之自信，我爸依旧劝我考公。再继续找不知道能不能撑到找到的那一天，不知道能不能找到合适的，找的这段时间又该学点什么技术提升自己，一切都好迷茫和焦虑感。",
    "content": "周四交接后，为期五个月左右的第二份工作也就此收尾，回去路上心里难受，因为没朋友所以只能跟爸妈说，不过再次证明跟爸妈说也得不到什么好的慰藉，他们只会说那就再找没什么大不了，我可能更想听到“那就休息一下吧”。总之跟他们说完更烦了，我妈对我有迷之自信，我爸依旧劝我考公。再继续找不知道能不能撑到找到的那一天，不知道能不能找到合适的，找的这段时间又该学点什么技术提升自己，一切都好迷茫和焦虑感。"
