    "content": "最近做了一个小项目： AI Zombie Video ，想在 V2EX 分享一下，也欢迎大家提建议。 它是一个比较垂直的 AI 视频生成工具：上传两张成年人的照片，就能生成一段 15 秒的末日题材短片。 大致是这样的故事： 一个人还保持清醒，面对已经变成丧尸的爱人 最后放下武器，两人拥抱 画面切换到温暖的回忆场景 整个故事流程是预设好的，不需要自己写复杂的 prompt ，也不需要把多段视频再导入剪辑软件拼起来。 目前实现的功能： 两张照片生成一段 15 秒视频 支持竖屏和横屏 768P 输出，无水印 一次性付费，…"
