    "content": "新华社南京10月17日电（记者何磊静、邢拓）2026年“一带一路”记者组织论坛17日在江苏南京举行。围绕“交汇融通·向新向前·世界变局中的媒体变革”主题，来自50余个国家和地区的近百位记者组织负责人和媒体代表进行深入研讨交流。 此次论坛由中华全国新闻工作者协会、江苏省委宣传部和南京市人民政府联合主办。中宣部副部长、国务院新闻办公室主任莫高义出席并致辞。 中国记协主席何平在主旨演讲中表示，2026年，“齐”字当选“一带一路”年度汉字，蕴含着“于参差之中求齐一”的东方智慧。面对单边主义、保护主义抬头，我们更加需要弘扬和…"
