    "description": "新华社台北10月17日电（记者马欣然、李寒芳）台湾观光部门最新统计数据显示，今年1至8月，台湾民众赴大陆累计249.2万人次，同比增长19.63%，两岸人员往来保持相当规模并呈现增长态势。 统计数据显示，今年1至8月，大陆稳居台湾民众出境旅游第二大目的地。从月度数据看，3至8月单月赴大陆人次均超过30万，各月同比均实现两位数增长。其中，3月赴大陆人次同比增长32.34%。 值得注意的是，同期台湾民众整体出境人次同比增长15.24%，赴大…",
    "content": "新华社台北10月17日电（记者马欣然、李寒芳）台湾观光部门最新统计数据显示，今年1至8月，台湾民众赴大陆累计249.2万人次，同比增长19.63%，两岸人员往来保持相当规模并呈现增长态势。 统计数据显示，今年1至8月，大陆稳居台湾民众出境旅游第二大目的地。从月度数据看，3至8月单月赴大陆人次均超过30万，各月同比均实现两位数增长。其中，3月赴大陆人次同比增长32.34%。 值得注意的是，同期台湾民众整体出境人次同比增长15.24%，赴大陆人次增幅高于整体出境增幅，显示出强劲的市场需求。 “阿公阿嬷喜欢组团去新疆、云…"
