    "description": "特斯拉第二代 Roadster 电动跑车进行离地飞行演示，美国得克萨斯州。10月15日，特斯拉公司正式公布第二代 Roadster 电动跑车，分为 Performance 公路版、Thrust 赛道版和 Rocket 单座飞行版。三个版本车型均配备2G抓地力的主动吸力系统，百公里加速耗时低于1秒，最高时速超过370公里，其中 Rocket 飞行版车身配备10个航天冷气体推进器，能够实现短时间离地飞行。摄影师：Tesla",
    "content": "特斯拉第二代 Roadster 电动跑车进行离地飞行演示，美国得克萨斯州。10月15日，特斯拉公司正式公布第二代 Roadster 电动跑车，分为 Performance 公路版、Thrust 赛道版和 Rocket 单座飞行版。三个版本车型均配备2G抓地力的主动吸力系统，百公里加速耗时低于1秒，最高时速超过370公里，其中 Rocket 飞行版车身配备10个航天冷气体推进器，能够实现短时间离地飞行。摄影师：Tesla"
