    "author": "杨青,马浩然",
    "description": "重阳节到来之际，记者走进沈阳市皇姑区三台子街道牡丹社区。该社区建于1983年，3094户居民中60岁以上占比四成。 面对基础设施老化与老龄化双重压力，社区以“议事有答”民意恳谈会化解居民生活中的急难愁盼问题。 针对东北地区冬季气温低、楼体老化导致供暖效果差的难题，社区经多方沟通完成楼体保温改造。 社区食堂与义诊服务，以及珠心算、萨克斯、合唱等课程让老年生活更加多彩。跌倒检测等科技手段接入智慧养老平台，“喘息服务”为照料老人的家庭减负。 …",
    "content": "重阳节到来之际，记者走进沈阳市皇姑区三台子街道牡丹社区。该社区建于1983年，3094户居民中60岁以上占比四成。 面对基础设施老化与老龄化双重压力，社区以“议事有答”民意恳谈会化解居民生活中的急难愁盼问题。 针对东北地区冬季气温低、楼体老化导致供暖效果差的难题，社区经多方沟通完成楼体保温改造。 社区食堂与义诊服务，以及珠心算、萨克斯、合唱等课程让老年生活更加多彩。跌倒检测等科技手段接入智慧养老平台，“喘息服务”为照料老人的家庭减负。 社区组建8支志愿服务队，由居民认领设施维护，老年人从“被照顾者”变为“参与者”。…"
