    "link": "http://www.news.cn/20261017/ac90d0772cf14757b659c2bcf6e47e4d/c.html",
    "pub_date": "2026-10-17 21:39:29",
    "author": "郑直,张卉,岳晨星",
    "description": "新华社日本名古屋10月17日电 题：自信昂扬，勇敢追梦——访亚残运会开幕式旗手李羽洁、闫盼盼 新华社记者郑直、张卉、岳晨星 将在18日晚的爱知·名古屋亚残运会开幕式上担任中国体育代表团旗手的李羽洁、闫盼盼表示，他们希望展现出自信与昂扬的精神面貌，带动更多残障人士勇敢追逐梦想。 中国代表团17日公布了开幕式旗手人选，喜悦与惊讶是女子跆拳道运动员李羽洁和男子举重运动员闫盼盼得到消息后的第一反应。激动过后，他们也都感受到，这是一份荣誉与责任。…",
