    "content": "新华社沈阳10月17日电 辽宁省纪委监委17日通报，日前，经辽宁省委批准，辽宁省纪委监委对沈阳市委原常委、政法委原书记，沈阳市铁西区委原书记郭忠孝严重违纪违法问题进行了立案审查调查。 经查，郭忠孝丧失理想信念，背弃初心使命，政绩观错位，搞劳民伤财的“形象工程”“政绩工程”，对抗组织审查，履行全面从严治党主体责任不力；无视中央八项规定精神，接受可能影响公正执行公务的宴请，违规使用公务用车；违反组织原则，不按规定报告个人有关事项，在组织函询时不如实说明问题，在干部选拔任用等工作中为他人谋取利益；违规收受财物；违规干预和…"
