    "content": "新华社基辅10月17日电 乌克兰总统泽连斯基17日称，16日晚至17日晨，乌克兰能源系统遭大规模袭击，乌多地15处以上重要发电和输电设施被攻击。 泽连斯基在社交媒体发文称，俄罗斯在16日19时至17日7时动用320多架无人机及各类导弹，对乌克兰能源设施、多个城市和社区发动袭击。 泽连斯基还表示，在俄罗斯对乌能源系统发动袭击之际，美国却完全无视《2026年格雷厄姆制裁俄罗斯和伊朗法案》。他认为，该法案本应对俄罗斯施加有效压力，以推动冲突结束。 美国白宫于当地时间16日发布的消息显示，美国总统特朗普当日签署一份行政令，…"
