    "content": "新华社地拉那10月17日电（记者陈刚）阿尔巴尼亚新一轮抗议示威活动16日进入第四天，示威者与警方在首都地拉那持续发生暴力冲突。 本轮抗议始于13日。据当地媒体报道，阿学生13日在教育部前聚集，呼吁政府关注大学办学条件、教育成本等问题。当天下午，教育部附近发生冲突，部分示威者向警方及政府建筑投掷石块等物品，警方使用催泪瓦斯和水炮驱散人群。 当地时间16日晚，地拉那局势仍较为紧张，政府出动大批防暴警察驱散抗议人群。记者在地拉那街头看到，暴力事件造成当地公共机构、银行、企业及公共设施受损，阿教育部、司法部、央行遭到冲击。…"
