    "description": "10月17日是国家扶贫日，也是国际消除贫困日。 “认真落实常态化帮扶责任，坚决守牢不发生规模性返贫致贫底线”“努力让广大农民生活更加幸福美好”……“十五五”开局之年，习近平总书记的一系列重要论述，彰显党中央持之以恒巩固拓展脱贫攻坚成果的坚定决心。 今年是实施常态化帮扶的第一年。从打赢脱贫攻坚战，到设立5年过渡期，再到开展常态化帮扶，习近平总书记在不同阶段的重要部署，饱含着对人民群众的深厚感情，也彰显了对中国式现代化建设全局的深远考量。 …",
