    "pub_date": "2026-10-17 20:40:08",
    "author": "",
    "description": "中新网广州10月17日电 (记者 程景伟)据广交会新闻中心17日消息，截至目前，广交会全球合作伙伴网络已覆盖112个国家或地区，累计签约238家境外工商机构、行业协会及头部采购企业等。",
