    "content": "新华社北京10月17日电（记者韦骅、李春宇）2026北京马拉松开赛前夕，马拉松“破2”第一人塞巴斯蒂安·萨维17日在这里寄语跑者们创造佳绩。 在今年4月的伦敦马拉松赛上，肯尼亚人萨维以1小时59分30秒的成绩在男子组中率先撞线，成为历史上首位在马拉松正式比赛中突破两小时大关的选手。近日，萨维开启中国行，他在北京大学与学生互动，也到访天坛与跑者交流。18日，萨维还将亲临北马赛道，为选手助威。 在17日由运动品牌阿迪达斯组织的跑者见面会上，萨维说：“我知道北京马拉松在中国跑者心中的地位，我也非常开心能够见证这特殊的一天…"
