    "content": "新华社内蒙古乌兰察布10月17日电 题：“有高远目标，更有耐心有定力”——习近平总书记在内蒙古乌兰察布考察纪实 新华社记者张晓松、朱基钗 人民日报记者杜尚泽、胡泽曦 塞上秋意正浓，层林尽染，草木斑斓，大地风光无限。 10月16日，习近平总书记来到内蒙古自治区乌兰察布市考察调研。这是党的十八大以来，总书记第四次到内蒙古考察。 今年是“十五五”开局之年，明年内蒙古自治区将迎来成立80周年。中华大地上徐徐铺展的中国式现代化宏伟画卷中，“祖国北部边疆这道风景线”如今更加亮丽。 3年前那次考察，习近平总书记对内蒙古发展作出清…"
