    "pub_date": "2026-10-17 19:44:54",
    "author": "",
    "description": "我也遇到了 Chromium 屏幕亮度亮暗交替。我没有禁用 Chromium 硬件加速，只关闭了 KDE Plasma 系统设置/显示与监视器/显示器配置/扩展动态范围/启用 EDR 这个开关。现在不闪烁了。我这台电脑确实是 Intel + Nvidia 混合显卡。不知道有没有更好的方法",
    "content": "我也遇到了 Chromium 屏幕亮度亮暗交替。我没有禁用 Chromium 硬件加速，只关闭了 KDE Plasma 系统设置/显示与监视器/显示器配置/扩展动态范围/启用 EDR 这个开关。现在不闪烁了。我这台电脑确实是 Intel + Nvidia 混合显卡。不知道有没有更好的方法"
