    "content": "新华社北京10月17日电（记者王承昊）以“信”为主题的第十七届海峡两岸少儿美术大展北京展17日亮相北京今日美术馆，展出来自海峡两岸、港澳地区及马来西亚等地青少年创作的近500组作品。 10月17日，以“信”为主题的第十七届海峡两岸少儿美术大展北京展亮相北京今日美术馆。新华社记者 王承昊 摄 汉字“信”意蕴丰富，孩子们笔下的“信”更是千姿百态。新北少年以《传承的信念》挥笔绘古，将“信”化作赓续文脉的信念；厦门孩童的《一封旧信，游子乡愁》循着余光中《乡愁》的笔墨，让“信”承载起跨越海峡的绵长思念；金门学子用画笔对比事实…"
