    "author": "高文成",
    "description": "新华社伦敦10月17日电（记者高文成）英国海上贸易行动办公室17日连续发布两份通报说，两艘油轮当天在沙特阿拉伯朱拜勒附近海域遭到袭击，其中一艘遭“不明发射物”击中，另一艘遭火箭弹袭击。两艘油轮船员均确认安全。 根据通报，第一起事件发生于协调世界时16日9时（北京时间16日17时），地点位于朱拜勒东北约68海里（约合126公里）处。一艘油轮遭不明发射物击中，船上所有船员均已安全撤离，事发时尚无环境污染影响报告。 第二起事件发生于协调世界时…",
    "content": "新华社伦敦10月17日电（记者高文成）英国海上贸易行动办公室17日连续发布两份通报说，两艘油轮当天在沙特阿拉伯朱拜勒附近海域遭到袭击，其中一艘遭“不明发射物”击中，另一艘遭火箭弹袭击。两艘油轮船员均确认安全。 根据通报，第一起事件发生于协调世界时16日9时（北京时间16日17时），地点位于朱拜勒东北约68海里（约合126公里）处。一艘油轮遭不明发射物击中，船上所有船员均已安全撤离，事发时尚无环境污染影响报告。 第二起事件发生于协调世界时16日19时22分（北京时间17日3时22分），地点位于朱拜勒东北约78海里（约…"
