    "title": "赓续长征精神 奋进复兴征程丨特写：会师热土上的新农人",
    "link": "http://www.news.cn/20261017/e5eb7dfebddd4de3b270667c817631b4/c.html",
    "pub_date": "2026-10-17 19:13:37",
    "author": "孙鹏程,郎兵兵,司小萌",
    "description": "新华社兰州10月17日电 特写：会师热土上的新农人 新华社记者孙鹏程、郎兵兵、司小萌 金秋时节，陇中黄土高原的梯田层叠错落，在秋阳下铺展成黄绿相间的丰收图景。农时不等人，在秋收队伍中，就有红军后代李财库的身影。 今年30岁的李财库，家住甘肃省白银市会宁县会师镇范家湾村。国庆节前，李财库带着农机手，驾驶收割机向3000亩荞麦田发起“总攻”，将饱满的荞麦籽粒收归粮仓。这几天，他们又向着1000多亩土豆地发起“冲锋”，一颗颗金黄的土豆跃土而出…",
    "content": "新华社兰州10月17日电 特写：会师热土上的新农人 新华社记者孙鹏程、郎兵兵、司小萌 金秋时节，陇中黄土高原的梯田层叠错落，在秋阳下铺展成黄绿相间的丰收图景。农时不等人，在秋收队伍中，就有红军后代李财库的身影。 今年30岁的李财库，家住甘肃省白银市会宁县会师镇范家湾村。国庆节前，李财库带着农机手，驾驶收割机向3000亩荞麦田发起“总攻”，将饱满的荞麦籽粒收归粮仓。这几天，他们又向着1000多亩土豆地发起“冲锋”，一颗颗金黄的土豆跃土而出。 9月20日，在甘肃省白银市会宁县会师镇范家湾村，李财库驾驶收割机收割荞麦。新…"
