    "content": "长期以来，中国在多数跨国药企全球研发中的角色很明确：全球方案定完，中国补一套桥接数据、做注册申报；或者全球已上市多年，中国再启动本地临床试验。中国团队的核心工作主要是找医院、招病人。 诺和试图把顺序倒过来——从化合物开发期就讨论中国入组、剂型选择和注册路径，从源头缩短获批周期。 南方周末研究员 罗仙仙 责任编辑：黄金萍 很多人认识诺和诺德，是从司美格鲁肽开始。 （注：2026年9月，诺和诺德（Novo Nordisk）品牌名称更为诺和（Novo），故以下简称为“诺和”。） 这款药最初研发用于治疗2型糖尿病，通过模拟…"
