    "content": "17/10/2026 - 11:51 法国多地周六举行抗议示威和封锁行动。前黄背心运动的参与者、高中生、大学生、气候活动人士以及农民走上街头，抗议生活成本持续高企，并要求改善教育条件、保障公共服务和提高工资。 据法新社报道，法国各地已宣布约1500个集会、示威或封锁行动，地点涉及环岛、桥梁、收费站以及加油站等交通和能源设施。不过，部分原定举行抗议的地点周六上午尚未出现示威者，整体动员规模仍有待观察。 在法国西部城市雷恩，约20名参与者周六上午在一家大型购物中心附近设置路障，利用垃圾桶和大型托盘限制车辆通行。参与行动…"
