    "author": "由荟圆,郑梦雨,葛晨",
    "description": "新华社内罗毕10月17日电 通讯｜探索气候融资助力绿色农业发展的新路 新华社记者由荟圆 郑梦雨 葛晨 在肯尼亚穆拉雅郡的一处咖啡种植园，咖啡树种植在更高大的树木遮阴下，以保持土壤水分、改善农田生态；农民用有机肥替代部分化肥，探索更加环保的耕作方式。这些田间实践，正成为当地小农户应对农业生产挑战的一种尝试。 推动这些改变的，是肯尼亚青年创业者戈弗雷·诺埃尔正在探索并实践的一种新模式。今年9月，在浙江杭州举行的2026全球农创客大赛决赛上，…",
    "content": "新华社内罗毕10月17日电 通讯｜探索气候融资助力绿色农业发展的新路 新华社记者由荟圆 郑梦雨 葛晨 在肯尼亚穆拉雅郡的一处咖啡种植园，咖啡树种植在更高大的树木遮阴下，以保持土壤水分、改善农田生态；农民用有机肥替代部分化肥，探索更加环保的耕作方式。这些田间实践，正成为当地小农户应对农业生产挑战的一种尝试。 推动这些改变的，是肯尼亚青年创业者戈弗雷·诺埃尔正在探索并实践的一种新模式。今年9月，在浙江杭州举行的2026全球农创客大赛决赛上，诺埃尔团队凭借“东非农业数字互联”这一项目斩获金奖。 诺埃尔告诉记者，该项目主要…"
